function zoomMap(factor,clientX,clientY){const area=$('#map-area');if(!area)return;const rect=mapViewport(),px=(clientX??rect.left+rect.width/2)-rect.left,py=(clientY??rect.top+rect.height/2)-rect.top,old=mapCamera.scale,next=Math.max(mapCamera.min,Math.min(mapCamera.max,old*factor));mapCamera.x=px-(px-mapCamera.x)*(next/old);mapCamera.y=py-(py-mapCamera.y)*(next/old);mapCamera.scale=next;applyMapCamera()}
